import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, ThemeColors, ThemeSetArgs } from 'claude-code'

// art.js is generated by build-ukiyo.mjs: the scene, the frames and the palette.
import { BOARD_FILL, DEF, MESSAGES, SLIP_FILL, scene } from './art.js'
import { makeColors } from './make-colors.js'

// How full the context is, in 5% steps. The night pales and dawn rises with it.
const FILL = atom({ plugin: 'ukiyo-winter', key: 'fill' } as const, 0)

async function setFill($: EngineInterface, percent: number) {
  const step = Math.max(0, Math.min(100, Math.round(percent / 5) * 5))
  // Only a new step redraws the backdrop.
  if ((await read($, FILL)) !== step) {
    await update($, FILL, () => step)
  }
}

async function readFill($: EngineInterface) {
  try {
    const { context } = await $.session.usage()
    await setFill($, context.percent ?? 0)
  } catch {
    // No figures yet (a fresh session): the night stays as it is.
  }
}

// Prussian-blue night, grey snow day.
const { theme, problems } = makeColors(DEF)

// Paper slips for the person's messages, lacquer (night) or cedar (day) for Claude's.
const COLORS: ThemeColors = {
  ...theme,
  inputs: {
    light: { ...theme.inputs.light, ...MESSAGES.light },
    dark: { ...theme.inputs.dark, ...MESSAGES.dark },
  },
}

const SCENE_NAME = 'ukiyo-winter'

// The frames are a hairline and one small accent, 12 points deep.
const LOOK: ThemeSetArgs = {
  backdrop: { scene: SCENE_NAME, glass: { blur: 4, opacity: 0.45 } },
  colors: COLORS,
  style: {
    Text: { fontFamily: ['serif'], fontSize: 16, lineHeight: 25 },
    Heading: { fontFamily: ['serif'], fontWeight: 'semibold', letterSpacing: 0.3 },
    UserMessage: {
      fill: SLIP_FILL,
      backgroundColor: 'bg-user-message',
      color: 'text-user-message',
      padding: 18,
      rotate: -0.4,
    },
    AssistantMessage: {
      fill: BOARD_FILL,
      backgroundColor: 'bg-assistant-message',
      color: 'text-assistant-message',
      padding: 18,
    },
    ToolUse: {
      color: 'text-primary',
      fontFamily: ['serif'],
      backgroundColor: 'surface-1',
      borderColor: 'border',
      radius: 4,
      paddingX: 8,
    },
  },
}

const ENABLED = 'enabled'

// Hosts differ in what `theme.set` takes: some have no `style`, and some
// name a scene with `id` rather than `scene`. Each form is tried in turn,
// fullest first, and the reply says which parts this host draws.
const { style: _style, ...NO_STYLE } = LOOK
const LADDER: { label: string; look: ThemeSetArgs }[] = [
  { label: 'scene, colors, frames and type', look: LOOK },
  { label: 'scene and colors (no frames or type)', look: NO_STYLE },
  {
    label: 'scene and colors (no frames or type)',
    look: { ...NO_STYLE, backdrop: { id: SCENE_NAME } } as unknown as ThemeSetArgs,
  },
  { label: 'colors only', look: { colors: COLORS } },
]

async function applyLook($: EngineInterface) {
  const refused: string[] = []
  for (const step of LADDER) {
    try {
      const set = await $.theme.set(step.look)
      const note = refused.length === 0 ? '' : ` This app refused: ${refused.join('; ')}`
      return { set, drawn: step.label, note }
    } catch (error) {
      refused.push(String(error).replace(/^HooksError: ukiyo-winter: theme\.set: /, ''))
    }
  }
  throw new Error(refused.join('; '))
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'ukiyo',
      description: 'Ukiyo Winter theme: /ukiyo on, /ukiyo off',
    })

    // The line that would stop Desktop painting the colors, if a later build brings one.
    const unpainted = problems.find(line => line.startsWith("Desktop won't paint"))
    if (unpainted !== undefined) {
      $.ui.toast(`ukiyo-winter: ${unpainted}`)
    }

    // Off until the person turns it on; then it stays on in later sessions.
    if ((await $.store.get(ENABLED)) === true) {
      try {
        const { set, note } = await applyLook($)
        if (!set.isDrawn) {
          $.ui.status(`Ukiyo Winter: ${set.reason}`)
        }
        if (note !== '') {
          $.ui.toast(`Ukiyo Winter:${note}`)
        }
      } catch (error) {
        $.ui.toast(`Ukiyo Winter was refused: ${String(error)}`)
      }
    }

    const started = await next(e)
    // A resumed session opens at its own hour of the night.
    await readFill($)

    return started
  })

  // After each turn, the sky catches up with the context.
  on('turn.complete', async ($, e, next) => {
    const done = await next(e)
    await readFill($)

    return done
  })

  // Compaction is the dawn breaking; afterwards a fresh night begins.
  // If this hook fails, the compaction goes on regardless.
  on('session.compact', async ($, e, next) => {
    const isMain = e.agentId === undefined && e.trigger !== 'precompute'
    if (isMain) {
      await setFill($, 100)
    }
    const result = await next(e)
    // The usage figures lag a compaction until the next reply, so a fresh
    // night is set outright; a skipped compaction goes back to the figures.
    if (isMain && result.skip === undefined) {
      await setFill($, 0)
    }
    if (isMain && result.skip !== undefined) {
      await readFill($)
    }

    return result
  }).catch(($, e, next) => next(e))

  on('command.run', { command: 'ukiyo' }, async ($, e) => {
    const word = e.args.trim().toLowerCase()

    if (word === 'on') {
      let applied
      try {
        applied = await applyLook($)
      } catch (error) {
        return { text: `Ukiyo Winter was refused: ${String(error)}` }
      }
      await $.store.set(ENABLED, true)
      const { set, drawn, note } = applied

      return {
        text: set.isDrawn
          ? `Ukiyo Winter is on: ${drawn}. /ukiyo off brings back the app's own look.${note}`
          : `Ukiyo Winter is on, but nothing draws it here: ${set.reason}.${note}`,
      }
    }
    if (word === 'off') {
      await $.theme.clear()
      await $.store.set(ENABLED, false)

      return { text: 'Ukiyo Winter is off.' }
    }
    const isOn = (await $.store.get(ENABLED)) === true

    return { text: `Ukiyo Winter is ${isOn ? 'on' : 'off'}. Use /ukiyo on or /ukiyo off.` }
  })

  on('ui.render', { component: 'Backdrop' }, async ($, e, next) => {
    // A host that names scenes by `id` passes that instead of `scene`.
    const props = e.props as { scene?: string; id?: string }
    const name = props.scene ?? props.id
    if (name !== SCENE_NAME || (e.surface !== 'desktop' && e.surface !== 'mobile')) {
      return next(e)
    }
    const { Svg } = $.ui.resolve(e)
    // Reading the fill here redraws the backdrop whenever it changes.
    const fill = await read($, FILL)

    return <Svg source={scene(fill)} alt="A castle under the moon in falling snow; dawn rises as the context fills" isInteractive />
  })
}
